var doc = app.activeDocument;
var ps = doc.paragraphStyles.add("Body Copy");
ps.characterAttributes.size = 11;
ps.paragraphAttributes.justification = Justification.LEFT;
ps.paragraphAttributes.spaceAfter = 6;
ps.applyTo(doc.textFrames[0].textRange, true);

var tf = app.activeDocument.textFrames[0];
var st = tf.story;
$.writeln(st.length + " chars in " + st.textFrames.length + " frames");
var paras = st.paragraphs;
for (var i = 0; i < paras.length; i++) {
  paras[i].characterAttributes.size = 12;
}

var tf = app.activeDocument.textFrames[0];
if (tf.kind == TextType.AREATEXT) {
  var tp = tf.textPath;
  var c = new RGBColor(); c.red = 255; c.green = 220; c.blue = 0;
  tp.filled = true; tp.fillColor = c;
  tp.stroked = true; tp.strokeWidth = 2;
}

var tf = app.activeDocument.textFrames[0];
var r = tf.textRange;
r.contents = "Summer Sale";
r.paragraphAttributes.justification = Justification.CENTER;
r.words[0].characterAttributes.size = 72;
r.changeCaseTo(CaseChangeType.UPPERCASE);
$.writeln(r.getTextRunLength());

var doc = app.activeDocument;
var pi = doc.rasterItems[0].trace();
var t = pi.tracing;
app.redraw();
$.writeln(t.pathCount + " paths, " + t.anchorCount + " anchors, " + t.usedColorCount + " colours");
var art = t.expandTracing();

var pi = app.activeDocument.placedItems[0].trace();
var o = pi.tracing.tracingOptions;
o.tracingMode = TracingModeType.TRACINGMODEBLACKANDWHITE;
o.threshold = 128;
o.tracingMethod = TracingMethodType.TRACINGMETHODABUTTING;
o.ignoreWhite = true;
app.redraw();
var art = pi.tracing.expandTracing();

var doc = app.activeDocument;
var m = app.getRotationMatrix(15);
m = app.concatenateScaleMatrix(m, 120, 120);
m = app.concatenateTranslationMatrix(m, 50, 0);
doc.selection[0].transform(m);
var tm = doc.textFrames[0].matrix;
$.writeln(Math.atan2(tm.mValueB, tm.mValueA) * 180 / Math.PI);
